macro_rules! DATA_ALLOC {
    ($t:ty, $p:expr, $alloc_pos:expr, $state:expr, $ctx_pos:expr, $ctx:expr) => {{
        DATA_STACK_ALLOC!($state, $t, $p, $alloc_pos, $ctx_pos, $ctx);
    }};
}

