macro_rules! DATA_STACK_ALLOC {
    ($state:expr, $type:ty, $ptr:expr, $alloc_pos:expr, $ctx_pos:expr, $ctx:expr) => {{
        loop {
            $alloc_pos = (unsafe { (*$state).data_stack_base }) as i64;
            if (core::mem::size_of::<$type>() as u64)
                > unsafe { (*$state).data_stack_size }.wrapping_sub(($alloc_pos) as u64)
            {
                let j: i32 = data_stack_grow($state, core::mem::size_of::<$type>() as i64);
                if j < 0 {
                    return j as i64;
                }
                if ($ctx_pos) != (1i32.wrapping_neg() as i64) {
                    DATA_STACK_LOOKUP_AT!($state, $type, $ctx, $ctx_pos);
                }
            }
            $ptr = unsafe { (*$state).data_stack }.wrapping_offset(($alloc_pos) as isize)
                as *mut $type;
            let __v: *mut __SlateRecord_sre_h_114 = $state;
            let __v2: u64 = unsafe { (*__v).data_stack_base };
            unsafe {
                (*__v).data_stack_base = __v2.wrapping_add(core::mem::size_of::<$type>() as u64);
            }
            if true {
                break;
            }
        }
    }};
}

macro_rules! DATA_STACK_LOOKUP_AT {
    ($state:expr, $type:ty, $ptr:expr, $pos:expr) => {
        loop {
            $ptr = unsafe { (*$state).data_stack }.wrapping_offset(($pos) as isize) as *mut $type;
            if true {
                break;
            }
        }
    };
}

macro_rules! DATA_STACK_POP_DISCARD {
    ($state:expr, $size:expr) => {
        loop {
            let __v: *mut __SlateRecord_sre_h_114 = $state;
            let __v2: u64 = unsafe { (*__v).data_stack_base };
            let __v3: u64 = __v2.wrapping_sub($size);
            unsafe {
                (*__v).data_stack_base = __v3;
            }
            if true {
                break;
            }
        }
    };
}

/// We add an explicit cast to memcpy here because MSVC has a bug when
/// compiling C code where it believes that `const void**` cannot be
/// safely casted to `void*`, see bpo-39943 for details.
/// We add an explicit cast to memcpy here because MSVC has a bug when
/// compiling C code where it believes that `const void**` cannot be
/// safely casted to `void*`, see bpo-39943 for details.
/// We add an explicit cast to memcpy here because MSVC has a bug when
/// compiling C code where it believes that `const void**` cannot be
/// safely casted to `void*`, see bpo-39943 for details.
macro_rules! DATA_STACK_POP {
    ($state:expr, $data:expr, $size:expr, $discard:expr) => {
        loop {
            unsafe {
                core::ptr::copy_nonoverlapping(
                    ((unsafe { (*$state).data_stack }
                        .wrapping_offset((*$state).data_stack_base as isize)
                        .wrapping_offset(-(($size) as isize)) as *const ())
                        as *const core::ffi::c_void) as *const u8,
                    ((($data) as *mut ()) as *mut core::ffi::c_void) as *mut u8,
                    (($size) as usize) as usize,
                )
            };
            if $discard {
                let __v: *mut __SlateRecord_sre_h_114 = $state;
                let __v2: u64 = unsafe { (*__v).data_stack_base };
                let __v3: u64 = __v2.wrapping_sub($size);
                unsafe {
                    (*__v).data_stack_base = __v3;
                }
            }
            if true {
                break;
            }
        }
    };
}

