macro_rules! FT_ATOMIC_STORE_INT {
    ($value:expr, $new_value:expr) => {
        unsafe {
            $value = $new_value;
        }
    };
}

macro_rules! FT_CLEAR_WEAKREFS {
    ($obj:expr, $weakref_list:expr) => {
        loop {
            if !$weakref_list.is_null() {
                unsafe { PyObject_ClearWeakRefs($obj) };
            }
            if true {
                break;
            }
        }
    };
}

macro_rules! GET_SKIP_ADJ {
    ($adj:expr, $code:expr, $end:expr, $skip:expr) => {{
        loop {
            VTRACE!();
            if ($code) >= $end {
                loop {
                    VTRACE!();
                    return 1i32.wrapping_neg();
                }
            }
            $skip = unsafe { *$code };
            VTRACE!();
            if ($skip.wrapping_sub(($adj) as u32) as u64)
                > (((unsafe { $end.offset_from(($code) as *mut u32) }) as i64) as u64)
            {
                loop {
                    VTRACE!();
                    return 1i32.wrapping_neg();
                }
            }
            let __v: *mut u32 = $code;
            let __v2: *mut u32 = __v.wrapping_offset(1 as isize);
            $code = __v2;
            if true {
                break;
            }
        }
    }};
}

macro_rules! LASTMARK_RESTORE {
    ($state:expr, $ctx:expr) => {
        loop {
            unsafe {
                (*$state).lastmark = (*$ctx).lastmark;
            }
            unsafe {
                (*$state).lastindex = (*$ctx).lastindex;
            }
            if true {
                break;
            }
        }
    };
}

/// The macros below should be used to protect recursive SRE(match)()
/// calls that *failed* and do *not* return immediately (IOW, those
/// that will backtrack). Explaining:
///
/// - Recursive SRE(match)() returned true: that's usually a success
///   (besides atypical cases like ASSERT_NOT), therefore there's no
///   reason to restore lastmark;
///
/// - Recursive SRE(match)() returned false but the current SRE(match)()
///   is returning to the caller: If the current SRE(match)() is the
///   top function of the recursion, returning false will be a matching
///   failure, and it doesn't matter where lastmark is pointing to.
///   If it's *not* the top function, it will be a recursive SRE(match)()
///   failure by itself, and the calling SRE(match)() will have to deal
///   with the failure by the same rules explained here (it will restore
///   lastmark by itself if necessary);
///
/// - Recursive SRE(match)() returned false, and will continue the
///   outside 'for' loop: must be protected when breaking, since the next
///   OP could potentially depend on lastmark;
///
/// - Recursive SRE(match)() returned false, and will be called again
///   inside a local for/while loop: must be protected between each
///   loop iteration, since the recursive SRE(match)() could do anything,
///   and could potentially depend on lastmark.
///
/// For more information, check the discussion at SF patch #712900.
