macro_rules! LASTMARK_SAVE {
    ($ctx:expr, $state:expr) => {
        loop {
            unsafe {
                (*$ctx).lastmark = (*$state).lastmark;
            }
            unsafe {
                (*$ctx).lastindex = (*$state).lastindex;
            }
            if true {
                break;
            }
        }
    };
}

